('ca-hap-gung-hanh','Cá hấp gừng hành','🐟',ARRAY['hap','viet','healthy'],TRUE,'2–3 người','["Cá 600 g","Gừng 15 g","Hành lá 20 g","Nước mắm 15 ml"]','["Làm sạch cá và khứa nhẹ hai mặt.","Rải gừng, hành lên cá.","Đặt đĩa chịu nhiệt vào tầng giữa.","Hấp theo thông số và kiểm tra cá chín tới."]','{"Shell S1":{"mode":"Steam","temp":"100°C","time":"16–20 phút","rack":"Tầng giữa"},"Vision S1 Pro":{"mode":"Steam","temp":"100°C","time":"16–18 phút","rack":"Tầng giữa"},"UBaker S1":{"mode":"Steam","temp":"100°C","time":"17–20 phút","rack":"Tầng 2"},"32L Steam Oven":{"mode":"Steam","temp":"100°C","time":"18–22 phút","rack":"Tầng 3"}}','published','2026-09'),
('banh-mi-bo-toi','Bánh mì bơ tỏi','🥖',ARRAY['banh'],TRUE,'2 người','["Bánh mì 200 g","Bơ lạt 35 g","Tỏi 10 g","Mùi tây 5 g"]','["Trộn bơ mềm với tỏi và mùi tây.","Phết đều lên bánh.","Xếp bánh một lớp trên khay.","Nướng đến khi mép bánh vàng giòn."]','{"Shell S1":{"mode":"Bake","temp":"170°C","time":"7–9 phút","rack":"Tầng giữa"},"Vision S1 Pro":{"mode":"Bake","temp":"175°C","time":"7–9 phút","rack":"Tầng giữa"},"UBaker S1":{"mode":"Bake","temp":"175°C","time":"8–10 phút","rack":"Tầng 2"},"32L Steam Oven":{"mode":"Bake","temp":"180°C","time":"8–10 phút","rack":"Tầng 3"}}','published','2026-09'),
('uc-ga-rau-cu','Ức gà rau củ ít dầu','🥗',ARRAY['healthy','nuong'],FALSE,'2 người','["Ức gà 350 g","Bông cải 180 g","Cà rốt 120 g","Dầu ô liu 8 ml"]','["Cắt rau củ kích thước đều.","Ướp gà nhẹ 15 phút.","Xếp một lớp, không chồng thực phẩm.","Nướng và đảo rau một lần giữa quá trình nếu cần."]','{"Shell S1":{"mode":"Bake","temp":"180°C","time":"18–22 phút","rack":"Tầng giữa"},"Vision S1 Pro":{"mode":"Bake","temp":"180°C","time":"18–22 phút","rack":"Tầng giữa"},"UBaker S1":{"mode":"Bake","temp":"185°C","time":"20–24 phút","rack":"Tầng 2"},"32L Steam Oven":{"mode":"Bake","temp":"185°C","time":"20–25 phút","rack":"Tầng 3"}}','published','2026-09'),
('ga-nuong-mat-ong','Gà nướng mật ong','🍗',ARRAY['nuong','viet'],FALSE,'3–4 người','["Gà nguyên con 1.2 kg","Mật ong 25 g","Nước mắm 20 ml","Tỏi băm 12 g","Dầu ăn 10 ml"]','["Lau khô gà, trộn gia vị và ướp ít nhất 30 phút.","Làm nóng lò 5 phút nếu model yêu cầu.","Đặt gà trên vỉ, khay hứng dầu ở tầng dưới.","Nướng theo thông số của model; kiểm tra phần dày nhất đã chín trước khi dùng."]','{"Shell S1":null,"Vision S1 Pro":{"mode":"Steam + Bake","temp":"180°C","time":"42–48 phút","rack":"Tầng 2"},"UBaker S1":{"mode":"Steam + Bake","temp":"180°C","time":"45–50 phút","rack":"Tầng 2"},"32L Steam Oven":{"mode":"Steam + Bake","temp":"185°C","time":"45–52 phút","rack":"Tầng 3"}}','published','2026-09') ON CONFLICT (slug) DO NOTHING;
